/// The smooth font for text the pixel font draws at `scale` (the same cell, drawn 1:1), if there is one: scale 1
/// stays the pixel font.
pub fn smooth(scale: u32) -> Option<&'static Font> {
    match scale {
        2 => Some(&SMOOTH2),
        3 => Some(&SMOOTH3),
        4 => Some(&SMOOTH4),
        5 => Some(&SMOOTH5),
        6 => Some(&SMOOTH6),
        7 => Some(&SMOOTH7),
        8 => Some(&SMOOTH8),
        _ => None,
    }
}
